import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';
import Navbar from '../components/Navbar';
import Footer from '../components/Footer';
import KibaShield from '../components/KibaShield';
import { IconUser, IconCheckCircle } from '../Icons';

const API = process.env.REACT_APP_API_URL || 'http://localhost:5000';

const dataOptions = [
  'National ID', 'CV or Resume', 'Certificate of Good Conduct',
  'Academic Certificate', 'Passport Photo', 'Work Permit', 'References Letter'
];

const StaffDashboard = () => {
  const { token, darkMode } = useAuth();
  const [activeTab, setActiveTab] = useState('post-job');
  const [customerId, setCustomerId] = useState('');
  const [purpose, setPurpose] = useState('');
  const [dataCategories, setDataCategories] = useState([]);
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [logs, setLogs] = useState([]);
  const [customers, setCustomers] = useState([]);
  const [jobs, setJobs] = useState([]);
  const [applications, setApplications] = useState([]);
  const [selectedJob, setSelectedJob] = useState(null);
  const [pose, setPose] = useState(1);
  const [shieldState, setShieldState] = useState('idle');
  const [jobForm, setJobForm] = useState({
    title: '', location: '', description: '', salaryRange: '',
    jobType: 'full_time', positions: 1, deadline: '',
    requirements: [''], skillCategories: [],
    requiredDocuments: [{ name: '', description: '' }]
  });
  const [jobMsg, setJobMsg] = useState('');
  const [jobError, setJobError] = useState('');

  useEffect(() => {
    fetchLogs();
    fetchCustomers();
    fetchMyJobs();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const fetchLogs = async () => {
    try {
      const res = await axios.get(`${API}/api/access/staff-logs`, { headers: { Authorization: `Bearer ${token}` } });
      setLogs(res.data);
    } catch (err) { console.error(err); }
  };

  const fetchCustomers = async () => {
    try {
      const res = await axios.get(`${API}/api/access/customers`, { headers: { Authorization: `Bearer ${token}` } });
      setCustomers(res.data);
    } catch (err) { console.error(err); }
  };

  const fetchMyJobs = async () => {
    try {
      const res = await axios.get(`${API}/api/jobs/staff/my-jobs`, { headers: { Authorization: `Bearer ${token}` } });
      setJobs(res.data);
    } catch (err) { console.error(err); }
  };

  const fetchApplications = async (jobId) => {
    try {
      const res = await axios.get(`${API}/api/applications/job/${jobId}`, { headers: { Authorization: `Bearer ${token}` } });
      setApplications(res.data);
    } catch (err) { console.error(err); }
  };

  const toggleCategory = (cat) => {
    setDataCategories(prev => prev.includes(cat) ? prev.filter(c => c !== cat) : [...prev, cat]);
  };

  const handlePostJob = async (e) => {
    e.preventDefault();
    setJobMsg('');
    setJobError('');
    setLoading(true);
    try {
      const payload = {
        ...jobForm,
        requirements: jobForm.requirements.filter(r => r.trim()),
        requiredDocuments: jobForm.requiredDocuments.filter(d => d.name.trim())
      };
      await axios.post(`${API}/api/jobs`, payload, { headers: { Authorization: `Bearer ${token}` } });
      setJobMsg('Job posted successfully. Applicants can now see and apply for this position.');
      setPose(2);
      setShieldState('success');
      setJobForm({ title: '', location: '', description: '', salaryRange: '', jobType: 'full_time', positions: 1, deadline: '', requirements: [''], skillCategories: [], requiredDocuments: [{ name: '', description: '' }] });
      fetchMyJobs();
      setTimeout(() => { setPose(1); setShieldState('idle'); }, 3000);
    } catch (err) {
      setJobError(err.response?.data?.message || 'Error posting job. Make sure your account is linked to a company by the administrator.');
      setPose(3);
      setShieldState('warning');
      setTimeout(() => { setPose(1); setShieldState('idle'); }, 2000);
    } finally {
      setLoading(false);
    }
  };

  const handleRequest = async (e) => {
    e.preventDefault();
    if (!customerId || !purpose || dataCategories.length === 0) {
      setResult({ error: 'Please select a customer, enter a purpose and select at least one data category' });
      setPose(3);
      setShieldState('warning');
      return;
    }
    setLoading(true);
    setPose(7);
    setShieldState('idle');
    setResult(null);
    try {
      const res = await axios.post(`${API}/api/access/request`, { customerId, purpose, dataCategories }, { headers: { Authorization: `Bearer ${token}` } });
      setResult({ success: true, data: res.data });
      setPose(2);
      setShieldState('success');
      fetchLogs();
      setTimeout(() => { setPose(1); setShieldState('idle'); }, 3000);
    } catch (err) {
      setResult({ success: false, data: err.response?.data });
      setPose(4);
      setShieldState('danger');
      setTimeout(() => { setPose(1); setShieldState('idle'); }, 3000);
    } finally {
      setLoading(false);
    }
  };

  const updateStatus = async (applicationId, status) => {
    try {
      await axios.put(`${API}/api/applications/status/${applicationId}`, { status }, { headers: { Authorization: `Bearer ${token}` } });
      fetchApplications(selectedJob);
    } catch (err) { console.error(err); }
  };

  const card = { background: darkMode ? '#1E293B' : '#fff', borderRadius: '16px', padding: '20px', boxShadow: '0 4px 24px rgba(30,58,95,0.08)', marginBottom: '16px' };
  const inputStyle = { width: '100%', padding: '11px 14px', border: '2px solid #E2E8F0', borderRadius: '10px', fontSize: '14px', fontFamily: 'Inter, sans-serif', background: darkMode ? '#0F172A' : '#fff', color: darkMode ? '#F1F5F9' : '#1E293B', outline: 'none', boxSizing: 'border-box' };
  const tabStyle = (active) => ({ padding: '9px 16px', borderRadius: '10px', border: 'none', fontWeight: 700, fontSize: '13px', cursor: 'pointer', fontFamily: 'Inter, sans-serif', background: active ? '#1E3A5F' : 'transparent', color: active ? '#fff' : '#64748B', transition: 'all 0.2s', whiteSpace: 'nowrap' });

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column', background: darkMode ? '#0F172A' : '#F8FAFC' }}>
      <Navbar />
      <div style={{ flex: 1, padding: '24px 16px', maxWidth: '1100px', margin: '0 auto', width: '100%', boxSizing: 'border-box' }}>
        <h1 style={{ fontSize: '24px', fontWeight: 800, color: darkMode ? '#F1F5F9' : '#1E3A5F', marginBottom: '4px' }}>Staff Dashboard</h1>
        <p style={{ color: '#64748B', fontSize: '14px', marginBottom: '20px' }}>Post jobs, review applications and request data access with consent verification</p>

        <div style={{ display: 'flex', gap: '8px', marginBottom: '20px', flexWrap: 'wrap' }}>
          {['post-job', 'applications', 'request-access', 'access-history'].map(t => (
            <button key={t} style={tabStyle(activeTab === t)} onClick={() => setActiveTab(t)}>
              {t === 'post-job' ? 'Post a Job' : t === 'applications' ? 'Applications' : t === 'request-access' ? 'Request Access' : 'Access History'}
            </button>
          ))}
        </div>

        <div style={{ display: 'flex', gap: '24px', alignItems: 'flex-start', flexWrap: 'wrap' }}>

          <div style={{ flex: 1, minWidth: '280px' }}>

            {activeTab === 'post-job' && (
              <div style={card}>
                <h3 style={{ fontSize: '16px', fontWeight: 700, color: darkMode ? '#F1F5F9' : '#1E3A5F', marginBottom: '16px' }}>Post a New Job</h3>
                <div style={{ marginBottom: '16px', background: '#EFF6FF', borderRadius: '10px', padding: '12px 14px' }}>
                  <p style={{ fontSize: '13px', color: '#1D4ED8', lineHeight: 1.6 }}>
                    Your account must be linked to a company by the administrator before you can post jobs. Contact your admin if you see an error.
                  </p>
                </div>
                {jobMsg && <div style={{ background: '#F0FDF4', color: '#10B981', border: '1px solid #BBF7D0', borderRadius: '10px', padding: '12px', fontSize: '13px', marginBottom: '12px' }}>{jobMsg}</div>}
                {jobError && <div style={{ background: '#FEF2F2', color: '#EF4444', border: '1px solid #FECACA', borderRadius: '10px', padding: '12px', fontSize: '13px', marginBottom: '12px' }}>{jobError}</div>}

                <form onSubmit={handlePostJob}>
                  <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '12px', marginBottom: '12px' }}>
                    <div>
                      <label style={{ display: 'block', fontSize: '12px', fontWeight: 600, color: '#64748B', marginBottom: '6px', textTransform: 'uppercase' }}>Job Title</label>
                      <input style={inputStyle} placeholder="e.g. Security Guard" value={jobForm.title} onChange={e => setJobForm({ ...jobForm, title: e.target.value })} required />
                    </div>
                    <div>
                      <label style={{ display: 'block', fontSize: '12px', fontWeight: 600, color: '#64748B', marginBottom: '6px', textTransform: 'uppercase' }}>Location</label>
                      <input style={inputStyle} placeholder="e.g. Nairobi CBD" value={jobForm.location} onChange={e => setJobForm({ ...jobForm, location: e.target.value })} required />
                    </div>
                    <div>
                      <label style={{ display: 'block', fontSize: '12px', fontWeight: 600, color: '#64748B', marginBottom: '6px', textTransform: 'uppercase' }}>Job Type</label>
                      <select style={inputStyle} value={jobForm.jobType} onChange={e => setJobForm({ ...jobForm, jobType: e.target.value })}>
                        <option value="full_time">Full Time</option>
                        <option value="part_time">Part Time</option>
                        <option value="contract">Contract</option>
                        <option value="internship">Internship</option>
                      </select>
                    </div>
                    <div>
                      <label style={{ display: 'block', fontSize: '12px', fontWeight: 600, color: '#64748B', marginBottom: '6px', textTransform: 'uppercase' }}>Number of Positions</label>
                      <input style={inputStyle} type="number" min="1" value={jobForm.positions} onChange={e => setJobForm({ ...jobForm, positions: Number(e.target.value) })} required />
                    </div>
                    <div>
                      <label style={{ display: 'block', fontSize: '12px', fontWeight: 600, color: '#64748B', marginBottom: '6px', textTransform: 'uppercase' }}>Application Deadline</label>
                      <input style={inputStyle} type="date" value={jobForm.deadline} onChange={e => setJobForm({ ...jobForm, deadline: e.target.value })} required />
                    </div>
                    <div>
                      <label style={{ display: 'block', fontSize: '12px', fontWeight: 600, color: '#64748B', marginBottom: '6px', textTransform: 'uppercase' }}>Salary Range (optional)</label>
                      <input style={inputStyle} placeholder="e.g. KES 30,000 to 50,000" value={jobForm.salaryRange} onChange={e => setJobForm({ ...jobForm, salaryRange: e.target.value })} />
                    </div>
                  </div>

                  <div style={{ marginBottom: '12px' }}>
                    <label style={{ display: 'block', fontSize: '12px', fontWeight: 600, color: '#64748B', marginBottom: '6px', textTransform: 'uppercase' }}>Job Description</label>
                    <textarea style={{ ...inputStyle, resize: 'vertical' }} rows={4} placeholder="Describe the role, responsibilities and what you are looking for..." value={jobForm.description} onChange={e => setJobForm({ ...jobForm, description: e.target.value })} required />
                  </div>

                  <div style={{ marginBottom: '12px' }}>
                    <label style={{ display: 'block', fontSize: '12px', fontWeight: 600, color: '#64748B', marginBottom: '10px', textTransform: 'uppercase' }}>Required Documents</label>
                    <p style={{ fontSize: '12px', color: '#64748B', marginBottom: '10px' }}>List the documents applicants must upload when applying</p>
                    {jobForm.requiredDocuments.map((doc, i) => (
                      <div key={i} style={{ display: 'flex', gap: '8px', marginBottom: '8px', flexWrap: 'wrap' }}>
                        <input
                          style={{ ...inputStyle, flex: 2, minWidth: '140px' }}
                          placeholder="Document name e.g. National ID"
                          value={doc.name}
                          onChange={e => {
                            const docs = [...jobForm.requiredDocuments];
                            docs[i].name = e.target.value;
                            setJobForm({ ...jobForm, requiredDocuments: docs });
                          }}
                        />
                        <input
                          style={{ ...inputStyle, flex: 3, minWidth: '160px' }}
                          placeholder="Description (optional)"
                          value={doc.description}
                          onChange={e => {
                            const docs = [...jobForm.requiredDocuments];
                            docs[i].description = e.target.value;
                            setJobForm({ ...jobForm, requiredDocuments: docs });
                          }}
                        />
                        {jobForm.requiredDocuments.length > 1 && (
                          <button type="button" onClick={() => setJobForm({ ...jobForm, requiredDocuments: jobForm.requiredDocuments.filter((_, idx) => idx !== i) })}
                            style={{ padding: '10px 14px', background: '#FEE2E2', color: '#EF4444', border: 'none', borderRadius: '10px', fontWeight: 700, cursor: 'pointer', fontFamily: 'Inter, sans-serif' }}>
                            Remove
                          </button>
                        )}
                      </div>
                    ))}
                    <button type="button" onClick={() => setJobForm({ ...jobForm, requiredDocuments: [...jobForm.requiredDocuments, { name: '', description: '' }] })}
                      style={{ padding: '9px 18px', background: '#E0F2FE', color: '#075985', border: 'none', borderRadius: '10px', fontWeight: 700, fontSize: '13px', cursor: 'pointer', fontFamily: 'Inter, sans-serif', marginTop: '4px' }}>
                      + Add Document
                    </button>
                  </div>

                  <button type="submit" disabled={loading}
                    style={{ width: '100%', padding: '14px', background: loading ? '#0EA5E9' : '#1E3A5F', color: '#fff', border: 'none', borderRadius: '12px', fontWeight: 700, fontSize: '15px', cursor: loading ? 'not-allowed' : 'pointer', fontFamily: 'Inter, sans-serif', marginTop: '8px', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px' }}>
                    {loading ? (
                      <>
                        <span style={{ width: '16px', height: '16px', border: '2px solid rgba(255,255,255,0.3)', borderTop: '2px solid #fff', borderRadius: '50%', display: 'inline-block', animation: 'kibashield-spin 0.8s linear infinite' }} />
                        Posting job...
                      </>
                    ) : 'Post Job'}
                  </button>
                </form>

                {jobs.length > 0 && (
                  <div style={{ marginTop: '24px' }}>
                    <h4 style={{ fontSize: '14px', fontWeight: 700, color: darkMode ? '#F1F5F9' : '#1E3A5F', marginBottom: '12px' }}>Your Posted Jobs</h4>
                    {jobs.map(job => (
                      <div key={job._id} style={{ background: darkMode ? '#0F172A' : '#F8FAFC', borderRadius: '12px', padding: '14px 16px', marginBottom: '10px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '8px' }}>
                        <div>
                          <p style={{ fontWeight: 700, fontSize: '14px', color: darkMode ? '#F1F5F9' : '#1E293B', marginBottom: '2px' }}>{job.title}</p>
                          <p style={{ fontSize: '12px', color: '#64748B' }}>{job.location} · {job.applicantCount} applicant{job.applicantCount !== 1 ? 's' : ''} · Deadline: {new Date(job.deadline).toLocaleDateString()}</p>
                        </div>
                        <button onClick={() => { setSelectedJob(job._id); setActiveTab('applications'); fetchApplications(job._id); }}
                          style={{ padding: '8px 16px', background: '#0EA5E9', color: '#fff', border: 'none', borderRadius: '8px', fontWeight: 700, fontSize: '12px', cursor: 'pointer', fontFamily: 'Inter, sans-serif' }}>
                          View Applicants
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}

            {activeTab === 'applications' && (
              <div style={card}>
                <h3 style={{ fontSize: '16px', fontWeight: 700, color: darkMode ? '#F1F5F9' : '#1E3A5F', marginBottom: '16px' }}>Job Applications</h3>

                {!selectedJob ? (
                  <div>
                    <p style={{ color: '#64748B', fontSize: '14px', marginBottom: '16px' }}>Select a job to view its applications:</p>
                    {jobs.length === 0 ? (
                      <p style={{ color: '#64748B', fontSize: '14px' }}>You have not posted any jobs yet. Go to Post a Job to get started.</p>
                    ) : jobs.map(job => (
                      <div key={job._id} style={{ background: darkMode ? '#0F172A' : '#F8FAFC', borderRadius: '12px', padding: '14px 16px', marginBottom: '10px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '8px' }}>
                        <div>
                          <p style={{ fontWeight: 700, fontSize: '14px', color: darkMode ? '#F1F5F9' : '#1E293B', marginBottom: '2px' }}>{job.title}</p>
                          <p style={{ fontSize: '12px', color: '#64748B' }}>{job.applicantCount} applicant{job.applicantCount !== 1 ? 's' : ''}</p>
                        </div>
                        <button onClick={() => { setSelectedJob(job._id); fetchApplications(job._id); }}
                          style={{ padding: '8px 16px', background: '#1E3A5F', color: '#fff', border: 'none', borderRadius: '8px', fontWeight: 700, fontSize: '12px', cursor: 'pointer', fontFamily: 'Inter, sans-serif' }}>
                          View Applications
                        </button>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div>
                    <button onClick={() => { setSelectedJob(null); setApplications([]); }} style={{ background: 'none', border: 'none', color: '#0EA5E9', fontWeight: 600, fontSize: '13px', cursor: 'pointer', fontFamily: 'Inter, sans-serif', marginBottom: '16px', padding: 0 }}>
                      ← Back to jobs
                    </button>
                    {applications.length === 0 ? (
                      <p style={{ color: '#64748B', fontSize: '14px' }}>No applications yet for this job.</p>
                    ) : applications.map(app => (
                      <div key={app._id} style={{ background: darkMode ? '#0F172A' : '#F8FAFC', borderRadius: '12px', padding: '16px', marginBottom: '12px' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', flexWrap: 'wrap', gap: '8px', marginBottom: '12px' }}>
                          <div>
                            <p style={{ fontWeight: 700, fontSize: '14px', color: darkMode ? '#F1F5F9' : '#1E293B', marginBottom: '2px' }}>{app.applicant?.fullName}</p>
                            <p style={{ fontSize: '12px', color: '#64748B' }}>ID: {app.applicant?.applicantId} · {app.applicant?.email || app.applicant?.phone}</p>
                            <p style={{ fontSize: '12px', color: '#64748B', marginTop: '2px' }}>Applied: {new Date(app.createdAt).toLocaleDateString()}</p>
                          </div>
                          <span style={{ padding: '4px 12px', borderRadius: '999px', fontSize: '11px', fontWeight: 700, height: 'fit-content', background: app.status === 'hired' ? '#D1FAE5' : app.status === 'rejected' ? '#FEE2E2' : app.status === 'shortlisted' ? '#FEF3C7' : '#E0F2FE', color: app.status === 'hired' ? '#065F46' : app.status === 'rejected' ? '#991B1B' : app.status === 'shortlisted' ? '#92400E' : '#075985' }}>
                            {app.status.replace('_', ' ').toUpperCase()}
                          </span>
                        </div>
                        <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
                          {['under_review', 'shortlisted', 'hired', 'rejected'].map(s => (
                            <button key={s} onClick={() => updateStatus(app._id, s)} disabled={app.status === s}
                              style={{ padding: '7px 14px', background: s === 'hired' ? '#10B981' : s === 'rejected' ? '#EF4444' : s === 'shortlisted' ? '#F59E0B' : '#0EA5E9', color: '#fff', border: 'none', borderRadius: '8px', fontWeight: 600, fontSize: '12px', cursor: app.status === s ? 'default' : 'pointer', fontFamily: 'Inter, sans-serif', opacity: app.status === s ? 0.5 : 1 }}>
                              {s === 'under_review' ? 'Under Review' : s === 'shortlisted' ? 'Shortlist' : s === 'hired' ? 'Hire' : 'Reject'}
                            </button>
                          ))}
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}

            {activeTab === 'request-access' && (
              <div style={card}>
                <h3 style={{ fontSize: '16px', fontWeight: 700, color: darkMode ? '#F1F5F9' : '#1E3A5F', marginBottom: '16px' }}>Request Data Access</h3>

                <div style={{ marginBottom: '16px', display: 'flex', justifyContent: 'center' }}>
                  <KibaShield pose={pose} shieldState={shieldState} />
                </div>

                {result && (
                  <div style={{ background: result.success ? '#F0FDF4' : '#FEF2F2', color: result.success ? '#065F46' : '#991B1B', border: `1px solid ${result.success ? '#BBF7D0' : '#FECACA'}`, borderRadius: '12px', padding: '13px 16px', marginBottom: '16px', fontSize: '14px', fontWeight: 500 }}>
                    {result.error || result.data?.message}
                  </div>
                )}

                <form onSubmit={handleRequest}>
                  <div style={{ marginBottom: '14px' }}>
                    <label style={{ display: 'block', fontSize: '12px', fontWeight: 600, color: '#64748B', marginBottom: '10px', textTransform: 'uppercase' }}>
                      Select customer ({customers.length} registered)
                    </label>
                    {customers.length === 0 ? (
                      <div style={{ background: darkMode ? '#0F172A' : '#F8FAFC', borderRadius: '12px', padding: '20px', textAlign: 'center' }}>
                        <p style={{ color: '#64748B', fontSize: '13px', margin: 0 }}>No customers have registered yet.</p>
                      </div>
                    ) : (
                      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', maxHeight: '240px', overflowY: 'auto', border: `1.5px solid ${darkMode ? '#334155' : '#E2E8F0'}`, borderRadius: '12px', padding: '8px' }}>
                        {customers.map(c => (
                          <button
                            key={c._id}
                            type="button"
                            onClick={() => setCustomerId(c._id)}
                            style={{
                              display: 'flex',
                              alignItems: 'center',
                              justifyContent: 'space-between',
                              gap: '10px',
                              padding: '10px 14px',
                              borderRadius: '10px',
                              border: '1.5px solid',
                              borderColor: customerId === c._id ? '#0EA5E9' : 'transparent',
                              background: customerId === c._id ? (darkMode ? 'rgba(14,165,233,0.12)' : '#E0F2FE') : (darkMode ? '#0F172A' : '#F8FAFC'),
                              cursor: 'pointer',
                              fontFamily: 'Inter, sans-serif',
                              textAlign: 'left',
                              transition: 'all 0.15s'
                            }}
                          >
                            <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                              <IconUser color={customerId === c._id ? '#0EA5E9' : '#64748B'} size={16} />
                              <div>
                                <p style={{ fontWeight: 700, fontSize: '13px', color: darkMode ? '#F1F5F9' : '#1E293B', margin: 0 }}>{c.fullName}</p>
                                <p style={{ fontSize: '11px', color: '#64748B', margin: '2px 0 0', fontFamily: 'Roboto Mono, monospace' }}>
                                  {c.applicantId || c.email || c.phone || 'No ID yet'}
                                </p>
                              </div>
                            </div>
                            {customerId === c._id && <IconCheckCircle color="#0EA5E9" size={18} />}
                          </button>
                        ))}
                      </div>
                    )}
                  </div>

                  <div style={{ marginBottom: '14px' }}>
                    <label style={{ display: 'block', fontSize: '12px', fontWeight: 600, color: '#64748B', marginBottom: '6px', textTransform: 'uppercase' }}>Purpose of access</label>
                    <input style={inputStyle} type="text" placeholder="e.g. Job application review" value={purpose} onChange={(e) => setPurpose(e.target.value)} />
                  </div>

                  <div style={{ marginBottom: '20px' }}>
                    <label style={{ display: 'block', fontSize: '12px', fontWeight: 600, color: '#64748B', marginBottom: '10px', textTransform: 'uppercase' }}>Data categories needed</label>
                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
                      {dataOptions.map(opt => (
                        <button key={opt} type="button" onClick={() => toggleCategory(opt)}
                          style={{ padding: '8px 14px', borderRadius: '999px', border: '2px solid', borderColor: dataCategories.includes(opt) ? '#0EA5E9' : '#E2E8F0', background: dataCategories.includes(opt) ? '#E0F2FE' : 'transparent', color: dataCategories.includes(opt) ? '#075985' : '#64748B', fontSize: '12px', fontWeight: 600, cursor: 'pointer', fontFamily: 'Inter, sans-serif', transition: 'all 0.2s' }}>
                          {dataCategories.includes(opt) ? '✓ ' : ''}{opt}
                        </button>
                      ))}
                    </div>
                  </div>

                  <button type="submit" disabled={loading}
                    style={{ width: '100%', padding: '14px', background: '#1E3A5F', color: '#fff', border: 'none', borderRadius: '12px', fontWeight: 700, fontSize: '15px', cursor: loading ? 'not-allowed' : 'pointer', opacity: loading ? 0.7 : 1, fontFamily: 'Inter, sans-serif' }}>
                    {loading ? 'Checking consent rules...' : 'Request Access'}
                  </button>
                </form>
              </div>
            )}

            {activeTab === 'access-history' && (
              <div style={card}>
                <h3 style={{ fontSize: '16px', fontWeight: 700, color: darkMode ? '#F1F5F9' : '#1E3A5F', marginBottom: '16px' }}>My Access History</h3>
                {logs.length === 0 ? (
                  <p style={{ color: '#64748B', fontSize: '14px' }}>No access requests made yet.</p>
                ) : (
                  <div style={{ overflowX: 'auto' }}>
                    <table style={{ width: '100%', borderCollapse: 'collapse', minWidth: '500px' }}>
                      <thead>
                        <tr style={{ background: '#1E3A5F' }}>
                          {['Customer', 'Purpose', 'Result', 'Date'].map(h => (
                            <th key={h} style={{ padding: '10px 14px', textAlign: 'left', color: '#fff', fontSize: '11px', fontWeight: 700, textTransform: 'uppercase' }}>{h}</th>
                          ))}
                        </tr>
                      </thead>
                      <tbody>
                        {logs.map((log, i) => (
                          <tr key={log._id} style={{ background: i % 2 === 0 ? (darkMode ? '#0F172A' : '#F8FAFC') : 'transparent' }}>
                            <td style={{ padding: '10px 14px', fontSize: '13px', color: darkMode ? '#CBD5E1' : '#1E293B', fontWeight: 500 }}>{log.customer?.fullName}</td>
                            <td style={{ padding: '10px 14px', fontSize: '13px', color: '#64748B' }}>{log.purpose}</td>
                            <td style={{ padding: '10px 14px' }}>
                              <span style={{ padding: '3px 10px', borderRadius: '999px', fontSize: '11px', fontWeight: 700, background: log.accessGranted ? '#D1FAE5' : '#FEE2E2', color: log.accessGranted ? '#065F46' : '#991B1B' }}>
                                {log.accessGranted ? 'GRANTED' : 'DENIED'}
                              </span>
                            </td>
                            <td style={{ padding: '10px 14px', fontSize: '12px', color: '#64748B', fontFamily: 'Roboto Mono, monospace' }}>{new Date(log.createdAt).toLocaleString()}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default StaffDashboard;
